#!/usr/bin/env bash\nset -euo pipefail\n\n# Load the script\nSCRIPT_PATH="$(dirname "${BASH_SOURCE[0]}")/../src/main.sh"\n\n# Mock du output\nexport MOCK_DU_OUTPUT=$'1000\t./dirA\n5000\t./dirB\n2000\t./dirC'\n\n# Capture output\noutput=$("$SCRIPT_PATH")\n\n# Helper to extract bar length for a given line prefix\nbar_len() {\n  local line="$1"\n  # Remove leading size and spaces\n  local rest="${line#*  }"\n  # Count leading #\n  local bar="${rest%% *}"\n  echo -n "${#bar}"\n}\n\n# Expected lengths (scaled to max 40)\n# max size 5000 => dirB 40, dirA 8, dirC 16\ndeclare -A expected=(\n  ["./dirA"]=8\n  ["./dirB"]=40\n  ["./dirC"]=16\n)\n\n# Iterate lines\nwhile IFS= read -r line; do\n  # Extract name (last field)\n  name="${line##* }"\n  len=$(bar_len "$line")\n  exp="${expected[$name]}"\n  if [[ -z "$exp" ]]; then\n    echo "Unexpected line: $line"\n    exit 1\n  fi\n  if (( len != exp )); then\n    echo "Bar length mismatch for $name: got $len, expected $exp"\n    exit 1\n  fi\ndone <<< "$output"\n\necho "All tests passed."
